    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background: #0b1020;
        color: #eef2ff;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgba(99, 102, 241, 0.28), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 30rem),
          #0b1020;
      }

      .support-page {
        width: min(100%, 42rem);
      }

      .contact-card {
        padding: clamp(1.5rem, 5vw, 3rem);
        border: 1px solid rgba(148, 163, 184, 0.2);
        border-radius: 1.5rem;
        background: rgba(15, 23, 42, 0.86);
        box-shadow: 0 1.5rem 5rem rgba(0, 0, 0, 0.38);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: #93c5fd;
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.5rem);
        line-height: 1;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: #cbd5e1;
        font-size: 1.0625rem;
        line-height: 1.7;
      }

      .contact-form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        color: #f8fafc;
        font-weight: 700;
      }

      .required-note,
      .helper-text {
        color: #a8b3cf;
        font-size: 0.925rem;
        line-height: 1.45;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        border: 1px solid #334155;
        border-radius: 0.875rem;
        padding: 0.875rem 1rem;
        background: #111827;
        color: #f8fafc;
        font: inherit;
        outline: none;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      input::placeholder {
        color: #64748b;
        opacity: 1;
      }

      input:focus {
        border-color: #60a5fa;
        background: #0f172a;
        box-shadow: 0 0 0 0.25rem rgba(96, 165, 250, 0.2);
      }

      button {
        min-height: 3.25rem;
        margin-top: 0.5rem;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        background: linear-gradient(135deg, #60a5fa, #818cf8);
        color: #08111f;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 1rem 2.5rem rgba(96, 165, 250, 0.26);
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          filter 160ms ease;
      }

      button:hover {
        filter: brightness(1.06);
        transform: translateY(-1px);
        box-shadow: 0 1.2rem 3rem rgba(96, 165, 250, 0.33);
      }

      button:focus-visible {
        outline: 0.25rem solid rgba(191, 219, 254, 0.7);
        outline-offset: 0.2rem;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }
    </style>
  </head>
  <body>
    <main id="root" class="support-page"></main>

    <script>
      const escapeHtml = (value) =>
