          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;",
          };

          return entities[character];
        });

      const Field = ({
        id,
        label,
        type = "text",
        autoComplete,
        required = false,
        placeholder,
        helperText,
      }) => {
        const helperId = helperText ? `${id}-helper` : undefined;

        return `
          <div class="form-field">
            <label for="${escapeHtml(id)}">
              ${escapeHtml(label)}${required ? '<span aria-hidden="true"> *</span>' : ""}
            </label>
            ${required ? '<span class="required-note">Required</span>' : ""}
            <input
              id="${escapeHtml(id)}"
              name="${escapeHtml(id)}"
              type="${escapeHtml(type)}"
              autocomplete="${escapeHtml(autoComplete)}"
              ${required ? "required" : ""}
              placeholder="${escapeHtml(placeholder)}"
              ${helperId ? `aria-describedby="${escapeHtml(helperId)}"` : ""}
            >
            ${
              helperText
                ? `<span id="${escapeHtml(helperId)}" class="helper-text">${escapeHtml(helperText)}</span>`
                : ""
            }
          </div>
        `;
      };

      const ContactForm = () => `
        <section class="contact-card" aria-labelledby="support-title">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Contact our team</h1>
          <p class="intro">
            Send us your details and a support specialist will use them to follow
            up with you.
          </p>

          <form class="contact-form">
            ${Field({
              id: "full-name",
              label: "Full name",
              autoComplete: "name",
              required: true,
              placeholder: "Alex Morgan",
            })}
            ${Field({
              id: "email-address",
              label: "Email address",
              type: "email",
              autoComplete: "email",
              required: true,
              placeholder: "alex@example.com",
            })}
            ${Field({
              id: "phone-number",
              label: "Phone number",
              type: "tel",
              autoComplete: "tel",
              placeholder: "+1 555 123 4567",
              helperText:
                "Optional. Use international format, such as +1 555 123 4567.",
            })}
            <button type="submit">Submit request</button>
          </form>
        </section>
      `;

      document.getElementById("root").innerHTML = ContactForm();
    </script>
  </body>
</html>
