              label: "Phone number",
              type: "tel",
              autoComplete: "tel",
              placeholder: "+1 555 123 4567",
              helperText:
                "Optional. Use international format, such as +1 555 123 4567.",
            })}
            <button type="submit">Submit request</button>
          </form>
        </section>
      `;

      document.getElementById("root").innerHTML = ContactForm();
    </script>
  </body>
